// Maps each selected submission to a draft post signed by The Anon.
// Throws (stopping the flow) when there is nothing to do, so the later
// update never runs with an empty key list (that would touch every row).
module.exports = async function (data) {
  const anon = [].concat(data.anon || [])[0];
  if (!anon) throw new Error('Persona "the-anon" not found');

  const submissions = [].concat(data.submissions || []).filter((s) => s && s.status !== 'accepted');
  if (submissions.length === 0) throw new Error('Nothing to publish: the selected submissions are already accepted');

  const slugify = (text) => text.normalize('NFKD').replace(/[\u0300-\u036f]/g, '').toLowerCase()
    .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 80);
  // Same estimate as the submit page preview: 200 words a minute
  const minutes = (text) => Math.max(1, Math.ceil(text.split(/\s+/).filter(Boolean).length / 200));

  return {
    keys: submissions.map((s) => s.id),
    posts: submissions.map((s) => ({
      status: 'draft',
      title: s.title || 'Submission ' + s.id,
      slug: slugify(s.title || '') || 'submission-' + s.id,
      content: s.content,
      persona: anon.id,
      reading_time: minutes(s.content || ''),
    })),
  };
};
